import { useState } from 'react';

import { Alert } from 'components';

import { StyledDataGovernanceBanner } from './DataGovernanceBanner.styles';

interface DataGovernanceBannerProps {
  onSeeUpdateStatus?: () => void;
  type?: 'neutral' | 'info' | 'success' | 'warning' | 'error';
  message: React.ReactNode;
  dataTestId?: string;
}

export const DataGovernanceBanner = ({
  onSeeUpdateStatus,
  type = 'neutral',
  message,
  dataTestId,
}: DataGovernanceBannerProps) => {
  const [isVisible, setIsVisible] = useState(true);
  if (!isVisible) return null;

  return (
    <StyledDataGovernanceBanner
      data-testid={dataTestId ? `${dataTestId}-banner` : undefined}
    >
      <Alert
        noBorderRadius
        type={type}
        message={message}
        dataTestId={dataTestId ? `${dataTestId}` : undefined}
        firstAction={
          onSeeUpdateStatus
            ? {
                onActionClick: onSeeUpdateStatus,
                actionMessage: 'See Update Status',
              }
            : undefined
        }
        closeButton
        onClose={() => setIsVisible(false)}
      />
    </StyledDataGovernanceBanner>
  );
};
